import{_ as t,o as a,a as o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"payment-method-development/getting-started.md","filePath":"payment-method-development/getting-started.md","lastUpdated":1789464754000}'),d={name:"payment-method-development/getting-started.md"};function n(i,e,s,h,l,c){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>A payment method in Bagisto is a class the checkout offers as a way to pay, added from a package through merged configuration. This section builds one method, then explains its configuration and its class, including the redirect flow a real gateway needs, without editing a core package.</p><h2 id="what-you-ll-build" tabindex="-1">What You&#39;ll Build <a class="header-anchor" href="#what-you-ll-build" aria-label="Permalink to &quot;What You&#39;ll Build&quot;">​</a></h2><p><strong><code>Webkul\\CustomStripePayment</code></strong>, a package that adds the payment method <code>custom_stripe_payment</code>:</p><ul><li>a <strong>Credit Card (Stripe)</strong> option, with a logo, on the checkout&#39;s payment step</li><li>an order placed as soon as the customer confirms, as with cash on delivery; the tutorial method doesn&#39;t charge a card</li><li>a <strong>Custom Stripe Payment</strong> section in the admin&#39;s payment method configuration, with its status, title, description, logo and sort order per channel</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Paths are relative to <code>packages/Webkul/CustomStripePayment/src</code>.</p><table tabindex="0"><thead><tr><th>Part</th><th>File</th><th>Plugs into</th></tr></thead><tbody><tr><td>Payment method configuration</td><td><code>Config/payment-methods.php</code></td><td>Merged into <code>config(&#39;payment_methods&#39;)</code>; its <code>class</code> key names the payment class</td></tr><tr><td>Payment class</td><td><code>Payment/CustomStripePayment.php</code></td><td>Extends <code>Webkul\\Payment\\Payment\\Payment</code>; <code>getRedirectUrl()</code> decides whether the customer leaves the site</td></tr><tr><td>System configuration</td><td><code>Config/system.php</code></td><td>Merged into <code>config(&#39;core&#39;)</code> as the section <code>sales.payment_methods.custom_stripe_payment</code>, which the class&#39;s <code>getConfigData()</code> reads</td></tr><tr><td>Service provider</td><td><code>Providers/CustomStripePaymentServiceProvider.php</code></td><td>Merges both files; listed in <code>bootstrap/providers.php</code></td></tr></tbody></table><p>The checkout lists every method whose <code>isAvailable()</code> returns true, sorted by its <code>sort</code> setting (<code>Webkul\\Payment\\Payment::getPaymentMethods()</code>), and checks the choice against that list again before placing the order. When the customer places it, a method whose <code>getRedirectUrl()</code> returns a URL sends them there and no order exists yet; a method that returns nothing has the order created at once. A gateway that redirects also needs routes and a controller for the return leg; <a href="./understanding-payment-class.html#the-redirect-flow">Understanding the Payment Class</a> walks through core&#39;s.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Bagisto 2.5, installed and running: see <a href="./../getting-started/installation.html">Installation</a>.</li><li>How a package is autoloaded and its provider registered: see <a href="./../package-development/getting-started.html">Package Development</a>.</li></ul><h2 id="the-path" tabindex="-1">The Path <a class="header-anchor" href="#the-path" aria-label="Permalink to &quot;The Path&quot;">​</a></h2><ol><li><a href="./create-your-first-payment-method.html">Creating Your First Payment Method</a>: build the package by hand and place an order with it. To scaffold it instead, see <a href="./../tools/package-generator.html#payment-and-shipping-method-packages">Package Generator</a>.</li><li><a href="./understanding-payment-configuration.html">Understanding Payment Configuration</a>: the <code>payment-methods.php</code> keys and the admin section.</li><li><a href="./understanding-payment-class.html">Understanding the Payment Class</a>: what the base class provides, availability, and the redirect, return and webhook flow.</li></ol><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Start by building the package.</p><p><strong>Continue to:</strong> <a href="./create-your-first-payment-method.html">Creating Your First Payment Method</a></p>',16)]))}const g=t(d,[["render",n]]);export{p as __pageData,g as default};
